content.content:
/** What is due on an amount at a rate: amount × rate / 100, rounded half up (away from zero) to two
 *  decimals; 'n/a' when there is no rate. */
export function due(amount: string, rate: string | undefined): string {
  if (rate === undefined) return 'n/a';
  const p = hundredths(amount) * hundredths(rate); // in 1/10000 of a hundredth
  const a = p < 0n ? -p : p;
  const r = (a + 5000n) / 10000n;
  return shown(p < 0n ? -r : r);
}

/** A claim's due: the figure fixed when it was settled, otherwise its amount at the current rate. */
export function claimDue(claim: Claim, rate: string | undefined): string {
  return claim.due ?? due(claim.amount, rate);
}

/** The due on claims: those that count with a live due, added up, at the rate (n/a when there is no rate,
 *  unless every claim that counts has a fixed due), plus the dues fixed when settled. */
export function dueTotal(claims: Claim[], rate: string | undefined): string {
  claims = claims.filter(counts);
  const fixed = claims.filter((c) => c.due !== null).map((c) => c.due as string);
  const live = claims.filter((c) => c.due === null);
  if (rate === undefined) return fixed.length > 0 && live.length === 0 ? sum(fixed) : 'n/a';
  return sum([due(total(live), rate), ...fixed]);
}

/** Two-decimal values added up, skipping 'n/a'. */
export function sum(values: string[]): string {
  return shown(values.filter((v) => v !== 'n/a').reduce((s, v) => s + hundredths(v), 0n));
}

